// replaceTranscript writes the full transcript content, replacing any existing transcript.
// Also removes any chunk files from a previous write and updates the content hash.
func (s *GitStore) replaceTranscript(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
	// Remove existing transcript files (base + any chunks)
	transcriptBase := sessionPath + paths.TranscriptFileName
	for key := range entries {
		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
			delete(entries, key)
		}
	}

	// Chunk the transcript (matches writeTranscript behavior)
	chunks, err := agent.ChunkTranscript(ctx, transcript.Bytes(), agentType)
	if err != nil {
		return fmt.Errorf("failed to chunk transcript: %w", err)
	}

	// Write chunk files
	for i, chunk := range chunks {
		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
		blobHash, err := CreateBlobFromContent(s.repo, chunk)
		if err != nil {
			return fmt.Errorf("failed to create transcript blob: %w", err)
		}
		entries[chunkPath] = object.TreeEntry{
			Name: chunkPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Update content hash
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return fmt.Errorf("failed to create content hash blob: %w", err)
	}
	hashPath := sessionPath + paths.ContentHashFileName
	entries[hashPath] = object.TreeEntry{
		Name: hashPath,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}

	return nil
}

// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
func (s *GitStore) ensureSessionsBranch(ctx context.Context) error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return err
	}
	emptyTreeHash, err = s.maybeMergeVercelConfig(ctx, emptyTreeHash)
	if err != nil {
		return err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
	if err != nil {
		return err
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}

func (s *GitStore) maybeMergeVercelConfig(_ context.Context, rootTreeHash plumbing.Hash) (plumbing.Hash, error) {
	repoRoot, rootErr := repositoryRoot(s.repo)
	if rootErr == nil {
		projectSettings, settingsErr := settings.LoadFromRepoRoot(repoRoot)
		if settingsErr == nil && projectSettings.Vercel {
			config := make(map[string]any)
			var existingContents string
			if rootTreeHash != plumbing.ZeroHash {
				tree, treeErr := s.repo.TreeObject(rootTreeHash)
				if treeErr != nil && !errors.Is(treeErr, plumbing.ErrObjectNotFound) {
					return plumbing.ZeroHash, fmt.Errorf("read metadata tree: %w", treeErr)
				}
				if treeErr == nil {
					file, fileErr := tree.File(vercelconfig.FileName)
					if fileErr == nil {
						contents, contentsErr := file.Contents()
						if contentsErr != nil {
							return plumbing.ZeroHash, fmt.Errorf("read %s from metadata branch: %w", vercelconfig.FileName, contentsErr)
						}
						existingContents = contents
						if unmarshalErr := json.Unmarshal([]byte(contents), &config); unmarshalErr != nil {
							config = make(map[string]any)
						}
					}
				}
			}

			vercelconfig.MergeDeploymentDisabled(config)
			output, err := vercelconfig.Marshal(config)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("marshal %s: %w", vercelconfig.FileName, err)
			}
			if string(output) == existingContents {
				return rootTreeHash, nil
			}

			blobHash, err := CreateBlobFromContent(s.repo, output)
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("create %s blob: %w", vercelconfig.FileName, err)
			}

			newTreeHash, err := UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{
				{Name: vercelconfig.FileName, Mode: filemode.Regular, Hash: blobHash},
			}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
			if err != nil {
				return plumbing.ZeroHash, fmt.Errorf("update metadata subtree with %s: %w", vercelconfig.FileName, err)
			}

			return newTreeHash, nil
		}
	}

	return rootTreeHash, nil
}

func repositoryRoot(repo *git.Repository) (string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("open worktree: %w", err)
	}
	return worktree.Filesystem.Root(), nil
}

// getFetchingTree returns a FetchingTree for the metadata branch.
// If a blob fetcher is configured on the store, File() calls on the returned
// tree will automatically fetch missing blobs from the remote.
func (s *GitStore) getFetchingTree(ctx context.Context) (*FetchingTree, error) {
	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return nil, err
	}
	return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher), nil
}

// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		// Local branch doesn't exist, try remote-tracking branch
		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
		ref, err = s.repo.Reference(remoteRefName, true)
		if err != nil {
			return nil, fmt.Errorf("sessions branch not found: %w", err)
		}
	}

